import { RateLimitedError } from "@/actions/_lib/action-errors";
import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import {
  passwordResetConfirmSchema,
  passwordResetRequestSchema,
} from "@/schemas/auth";
import {
  confirmPasswordReset,
  requestPasswordReset,
} from "@/server/services/auth-service";
import type { ActionResult } from "@/types/api";

const RESET_BUCKET = "auth:password-reset";

export async function requestPasswordResetAction(
  raw: unknown,
): Promise<ActionResult<null>> {
  const parsed = passwordResetRequestSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, RESET_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(RESET_BUCKET, verdict.resetAt);
    }

    await requestPasswordReset(parsed.data);
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

export async function confirmPasswordResetAction(
  raw: unknown,
): Promise<ActionResult<null>> {
  const parsed = passwordResetConfirmSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, RESET_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(RESET_BUCKET, verdict.resetAt);
    }

    await confirmPasswordReset(parsed.data);
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
import { z } from "zod";
import { emailSchema } from "./common";

const passwordSchema = z
  .string()
  .min(12, "use at least 12 characters")
  .max(128)
  .regex(/[a-z]/, "include a lowercase letter")
  .regex(/[A-Z]/, "include an uppercase letter")
  .regex(/[0-9]/, "include a digit");

export const loginSchema = z.object({
  email: emailSchema,
  password: z.string().min(1, "enter your password"),
  rememberMe: z.boolean().default(false),
});

export const registerSchema = z
  .object({
    name: z.string().min(1).max(80),
    email: emailSchema,
    password: passwordSchema,
    confirmPassword: z.string(),
    acceptTerms: z.literal(true, "you must accept the terms"),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "passwords do not match",
    path: ["confirmPassword"],
  });

export const passwordResetRequestSchema = z.object({
  email: emailSchema,
});

export const passwordResetConfirmSchema = z
  .object({
    token: z.string().min(16),
    password: passwordSchema,
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: "passwords do not match",
    path: ["confirmPassword"],
  });

export type LoginInput = z.infer<typeof loginSchema>;
export type RegisterInput = z.infer<typeof registerSchema>;
export type PasswordResetRequestInput = z.infer<
  typeof passwordResetRequestSchema
>;
export type PasswordResetConfirmInput = z.infer<
  typeof passwordResetConfirmSchema
>;
import { z } from "zod";
import { isoTimestampSchema, orgIdSchema, userIdSchema } from "./common";

/** Name of the session cookie checked by `src/proxy.ts`. */
export const SESSION_COOKIE_NAME = "taskflow_session";

export const sessionTokenSchema = z
  .string()
  .min(32)
  .max(256)
  .regex(/^[A-Za-z0-9_.-]+$/, "malformed session token");

export const sessionPrincipalSchema = z.object({
  userId: userIdSchema,
  email: z.email(),
  activeOrgId: orgIdSchema.nullable(),
  expiresAt: isoTimestampSchema,
});

export const switchOrgSchema = z.object({
  orgId: orgIdSchema,
});

export type SessionPrincipalInput = z.infer<typeof sessionPrincipalSchema>;
export type SwitchOrgInput = z.infer<typeof switchOrgSchema>;

