new='''/** Returns the token only while it is unexpired and has not been used. */
export async function findLiveResetToken(
  tokenHash: string,
): Promise<ResetToken | null> {
  const row = getDb()
    .select()
    .from(passwordResetTokens)
    .where(
      and(
        eq(passwordResetTokens.tokenHash, tokenHash),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
      ),
    )
    .get();

  if (!row) return null;

  return {
    id: row.id,
    userId: brandId<UserId>(row.userId),
    expiresAt: toIsoTimestamp(row.expiresAt),
  };
}

/**
 * Single use: consuming a token is what stops a reset link being replayed.
 * Returns `false` when the token was already used, so two concurrent
 * submissions of one link cannot both succeed.
 */
export async function consumeResetToken(id: string): Promise<boolean> {
  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(eq(passwordResetTokens.id, id), isNull(passwordResetTokens.usedAt)),
    )
    .returning({ id: passwordResetTokens.id })
    .all();
  return rows.length > 0;
}

/**
 * Retires every still-unused token of one user — called before a new link is
 * issued and once a reset completes, so only the newest link can ever work.
 */
export async function retireResetTokensForUser(userId: UserId): Promise<void> {
  const stamp = toIsoTimestamp(new Date());
  getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(
        eq(passwordResetTokens.userId, userId),
        isNull(passwordResetTokens.usedAt),
      ),
    )
    .run();
}
'''
