    expect(await resolveSession(a1.token)).toBeNull();
    expect(await resolveSession(a2.token)).not.toBeNull();
    expect(await resolveSession(b1.token)).not.toBeNull();
    await destroySession(a1.token); await destroySession("nonsense");
    const row = getDb().select().from(sessions).where(eq(sessions.tokenHash, hashToken(a2.token))).get()!;
    await logout(row.id as never);
    await logout("unknown" as never);
    expect(await resolveSession(a2.token)).toBeNull();
    expect(await resolveSession(b1.token)).not.toBeNull();
    const a3 = await login({ email: "alice@example.com", password: PW, rememberMe: false });
    expect(await resolveSession(a3.token)).not.toBeNull();
  });

  it("remember me ttl", async () => {
    vi.useFakeTimers({ toFake: ["Date"] }); vi.setSystemTime(new Date("2026-01-01T00:00:00Z"));
    await mk("Alice", "alice@example.com");
    const short = await login({ email: "alice@example.com", password: PW, rememberMe: false });
    const long = await login({ email: "alice@example.com", password: PW, rememberMe: true });
    vi.setSystemTime(new Date("2026-01-01T23:59:00Z"));
    expect(await resolveSession(short.token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-01-02T00:01:00Z"));
    expect(await resolveSession(short.token)).toBeNull();
    expect(await resolveSession(long.token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-01-30T23:00:00Z"));
    expect(await resolveSession(long.token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-01-31T00:01:00Z"));
    expect(await resolveSession(long.token)).toBeNull();
  });

  it("reset flow", async () => {
    vi.useFakeTimers({ toFake: ["Date"] }); vi.setSystemTime(new Date("2026-01-01T00:00:00Z"));
    await mk("Alice", "alice@example.com"); await mk("Bob", "bob@example.com");
    const laptop = await login({ email: "alice@example.com", password: PW, rememberMe: true });
    const bob = await login({ email: "bob@example.com", password: PW, rememberMe: true });
    sent = [];
    await requestPasswordReset({ email: "BOB@example.com" });
    const bobTok = lastToken();
    await requestPasswordReset({ email: "Alice@Example.com" });
    expect(sent.length).toBe(2);
    const first = lastToken();
    await requestPasswordReset({ email: "alice@example.com" });
    const second = lastToken();
    await expect(confirmPasswordReset({ token: first, password: NEWPW, confirmPassword: NEWPW })).rejects.toThrow();
    vi.setSystemTime(new Date("2026-01-01T00:59:00Z"));
    await confirmPasswordReset({ token: second, password: NEWPW, confirmPassword: NEWPW });
    await expect(confirmPasswordReset({ token: second, password: NEWPW, confirmPassword: NEWPW })).rejects.toThrow();
    expect(await resolveSession(laptop.token)).toBeNull();
    expect(await resolveSession(bob.token)).not.toBeNull();
    await expect(login({ email: "alice@example.com", password: PW, rememberMe: false })).rejects.toThrow();
    await login({ email: "alice@example.com", password: NEWPW, rememberMe: false });
    // bob's link unaffected by alice's requests, but expires after 60 min
    vi.setSystemTime(new Date("2026-01-01T01:01:00Z"));
    await expect(confirmPasswordReset({ token: bobTok, password: NEWPW, confirmPassword: NEWPW })).rejects.toThrow();
    sent = [];
    await requestPasswordReset({ email: "nobody@example.com" });
    expect(sent.length).toBe(0);
  });

  it("bob's link survives alice's requests", async () => {
    await mk("Alice", "alice@example.com"); await mk("Bob", "bob@example.com");
    await requestPasswordReset({ email: "bob@example.com" });
    const bobTok = lastToken();
    await requestPasswordReset({ email: "alice@example.com" });
    await confirmPasswordReset({ token: bobTok, password: NEWPW, confirmPassword: NEWPW });
  });

  it("per-account throttling", async () => {
    vi.useFakeTimers({ toFake: ["Date"] }); vi.setSystemTime(new Date("2026-01-01T00:00:00Z"));
    await mk("Alice", "alice@example.com"); await mk("Bob", "bob@example.com");
    let throttled = false;
    for (let i = 0; i < 100; i++) {
      try { await login({ email: i % 2 ? "ALICE@example.com" : "alice@example.com", password: "wrong", rememberMe: false }); }
      catch (e) { if (/too many/i.test((e as Error).message)) { throttled = true; break; } }
    }
    expect(throttled).toBe(true);
    await expect(login({ email: "alice@example.com", password: PW, rememberMe: false })).rejects.toThrow(/too many/i);
    await login({ email: "bob@example.com", password: PW, rememberMe: false });
    sent = [];
    await requestPasswordReset({ email: "alice@example.com" });
    expect(sent.length).toBe(1);
    await confirmPasswordReset({ token: lastToken(), password: NEWPW, confirmPassword: NEWPW });
    await expect(login({ email: "alice@example.com", password: NEWPW, rememberMe: false })).rejects.toThrow(/too many/i);
    vi.setSystemTime(new Date("2026-01-01T01:00:00Z"));
    await login({ email: "alice@example.com", password: NEWPW, rememberMe: false });
    // reset request throttling
    sent = [];
    const cap = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < cap + 3; i++) await requestPasswordReset({ email: "alice@example.com" });
    expect(sent.length).toBe(cap);
    await requestPasswordReset({ email: "bob@example.com" });
    expect(sent.length).toBe(cap + 1);
    await login({ email: "bob@example.com", password: PW, rememberMe: false });
  });
});
